mapper.select:
SELECT COUNT(*)
FROM clue
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND in_shared_pool = 0

SELECT COUNT(*)
FROM customer
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND in_shared_pool = 0

SELECT COUNT(*)
FROM opportunity
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}

SELECT COALESCE(SUM(amount), 0)
FROM opportunity
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}

SELECT COUNT(*)
FROM crm_contract
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND signed_date >= #{monthStart}
  AND signed_date <= #{monthEnd}

SELECT COALESCE(SUM(amount), 0)
FROM crm_contract
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND signed_date >= #{monthStart}
  AND signed_date <= #{monthEnd}

SELECT COUNT(*)
FROM crm_order
WHERE organization_id = #{orgId}
  AND create_user = #{ownerId}
  AND create_time >= #{monthStart}
  AND create_time <= #{monthEnd}

SELECT COALESCE(SUM(total_amount), 0)
FROM crm_order
WHERE organization_id = #{orgId}
  AND create_user = #{ownerId}
  AND create_time >= #{monthStart}
  AND create_time <= #{monthEnd}

SELECT COUNT(*)
FROM crm_follow_plan
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND status = 'pending'

SELECT COUNT(*)
FROM crm_contract
WHERE organization_id = #{orgId}
  AND owner = #{ownerId}
  AND end_date >= #{now}
  AND end_date <= #{expireTime}

SELECT COUNT(*)
FROM crm_payment_plan
WHERE expected_date < #{now}
  AND status = 'pending'
  AND EXISTS (
      SELECT 1 FROM crm_contract c
      WHERE c.id = crm_payment_plan.contract_id
        AND c.organization_id = #{orgId}
        AND c.owner = #{ownerId}
  )

SELECT biz_type AS bizType,
       biz_id AS bizId,
       content AS bizName,
       'followed' AS action,
       create_time AS operateTime,
       create_user AS operatorName
FROM crm_follow_record
WHERE organization_id = #{orgId}
  AND create_user = #{userId}
  AND create_time >= #{sevenDaysAgo}
ORDER BY create_time DESC
LIMIT #{limit}
